fn run_cache(matches: &clap::ArgMatches) -> Result<()> {
    if matches.is_present("build-cache") {
        let source_dir = matches.value_of("cache-source").map(Path::new);
        let target_dir = matches.value_of("cache-target").map(Path::new);

        let blank = matches.is_present("cache-blank");

        let assets = HighlightingAssets::from_files(source_dir, blank)?;
        assets.save(target_dir)?;
    } else if matches.is_present("clear-cache") {
        clear_assets();
    }

    Ok(())
}

